/**
 * Sonic signature (ADR-0016, gate E "Two, then one"). `public/brand-signature.wav` is GENERATED by
 * brand/scripts/build.mjs (~1.4 s). It plays once per app start, after the first screen rendered, unless the
 * user turned "Startup sound" off. The choice lives in the shared prefs blob (`startupSound`; missing = on,
 * the TV default).
 */
import { readPrefs, writePrefs } from "./prefs.ts";

/** Relative on purpose: the widget runs from file:// on Tizen and webOS, where "/x" is the filesystem root. */
export const BRAND_SOUND_URL = "./brand-signature.wav";
export const BRAND_SOUND_VOLUME = 0.6;

export function startupSoundEnabled(prefs: Record<string, unknown> = readPrefs()): boolean {
    return prefs.startupSound !== false;
}

export function setStartupSound(on: boolean): void {
    writePrefs({ startupSound: on });
}

let played = false;

/** At most once per app start (the tree re-keys on a language change). Autoplay rejections are ignored. */
export function playStartupSound(): void {
    if (played) return;
    played = true;
    if (!startupSoundEnabled()) return;
    try {
        const audio = new Audio(BRAND_SOUND_URL);
        audio.volume = BRAND_SOUND_VOLUME;
        audio.play().catch(() => undefined);
    } catch { /* no audio element / no output device */ }
}
